// 아래 함수는 그대로 두세요. 검사기가 부릅니다
function check(prices, ms) {
  const result = totalAfterDelay(prices, ms);

  if (typeof result !== 'object') {
    return '약속이 아니라 값을 그대로 돌려줬습니다';
  }

  return result;
}

function totalAfterDelay(prices, ms) {
  return new Promise((resolve) => {
    setTimeout(() => {
      let total = 0;

      for (const price of prices) {
        total = total + price;
      }

      resolve(total);
    }, ms);
  });
}
